    "গ. একজন ভালো শিক্ষক ব্যক্তিত্ব সম্পন্ন হবেন। তিনি— (১) পরিষ্কার-পরিচ্ছন্ন থাকবেন; (২) শালীন, মার্জিত ও ব্যক্তিত্বস্ফূরক পোশাক পরিধান করবেন; (৩) বিশুদ্ধ উচ্চারণ ও প্রকাশভঙ্গির অধিকারী হবেন; (৪) মানসিক ভারসাম্য বজায় রাখবেন; (৫) নিয়মনীতির ক্ষেত্রে কঠোর হবেন; (৬) সুস্থ মন ও দেহের অধিকারী হবেন। ঘ. একজন ভালো শিক্ষক ছাত্রদের প্রতি মমত্ববোধ ও ভালোবাসা সম্পন্ন হবেন। তিনি— (১) স্নেহ-মমতা দিয়ে শিক্ষার্থীদের পাঠদান করবেন। (২) সকল শিক্ষার্থীকে সমান চোখে দেখবেন। (৩) ছাত্রদের মাঝে জ্ঞান লাভের উৎসাহ তৈরি করবেন। (৪) প্রয়োজনে একটি বিষয় বার বার বলবেন। (৫) ছাত্রদের একান্ত আপনজন হবেন। (৬) শিক্ষার্থীদের অহেতুক ধমক দেবেন না অথবা শাসন করবেন না। (৭) তাদেরকে প্রহার বা তাদের প্রতি নির্মমতা প্রদর্শন করবেন না বরং দরদি মন নিয়ে তাদের ভুলগুলো ধরিয়ে দেবেন। প্রখ্যাত সাহাবি মুয়াবিয়া ইবনুল হাকাম আস-সুলামি রাসূল (স.) সম্পর্কে বলেন, “আমি তাঁর পূর্বে ও পরে তাঁর চেয়ে সুন্দর শিক্ষাদানকারী শিক্ষক আর দেখিনি। আল্লাহর কসম তিনি আমাকে বকাঝকা করেননি, মারেননি এবং গালমন্দও করেননি।” (মুসলিম) ঙ. একজন ভালো শিক্ষক বিচক্ষণ হবেন। চ. একজন ভালো শিক্ষক প্রতিষ্ঠানের প্রতি হবেন আন্তরিক ও দরদি।"
