    "সততা, সদাচার, সৌজন্যমূলক আচরণ, সুন্দর স্বভাব, মিষ্টি কথা ও উন্নত চরিত্র— এ সবকিছুর সমন্বয় হলো নৈতিকতা। একজন মানুষের দৈনন্দিন জীবনের চাল-চলন, উঠা-বসা, আচার-ব্যবহার, লেন-দেন সবকিছুই যখন প্রশংসনীয় ও গ্রহণযোগ্য হয় তখন তাকে নৈতিক গুণাবলি সম্পন্ন ব্যক্তি বলে। এই নৈতিকতা সম্পন্ন ব্যক্তিকে রাসূলুল্লাহ (স.) সর্বোত্তম লোক বলে অভিহিত করেছেন। তিনি বলেছেন, “নিশ্চয় তোমাদের মধ্যে ঐ ব্যক্তি উত্তম, যার চরিত্র উত্তম।” (বুখারি ও মুসলিম) নৈতিকতা হলো ব্যক্তির মৌলিক মানবীয় গুণ এবং জীবনের শ্রেষ্ঠ সম্পদ। নীতিহীন ও চরিত্রহীন মানুষ চতুষ্পদ জন্তুর চেয়েও নিকৃষ্ট। (সূরা আল-আরাফ, আয়াত ১৭৯)",
    "নৈতিকতার গুরুত্ব: ইসলামি জীবন ব্যবস্থায় নৈতিকতার গুরুত্ব অপরিসীম। মানুষকে ইমান ও নৈতিকতা শিক্ষা দেওয়ার জন্য মহানবি (স.) প্রেরিত হয়েছিলেন। তিনি বলেন, “আমি মহান নৈতিক গুণাবলিকে পরিপূর্ণতা দান করার জন্যই প্রেরিত হয়েছি।” (বুখারি) মহানবি হযরত মুহাম্মদ (স.) নীতিবান লোককে পরিপূর্ণ মুমিন হিসেবে অভিহিত করে বলেন— অর্থ: “চরিত্রের বিচারে যে লোকটি উত্তম মুমিনদের মধ্যে সেই পূর্ণ ইমানের অধিকারী।” (তিরমিযি) জনৈক ব্যক্তি হযরত মুহাম্মদ (স.)-এর নিকট জানতে চাইলেন মহান আল্লাহ মানুষকে অনেক কিছু দান করেছেন; এর মধ্যে সবচেয়ে মূল্যবান দান কোনটি? নবি করিম (স.) বললেন, “সবচেয়ে মূল্যবান দান সুন্দর চরিত্র।” তাই বলা যায় যে, নৈতিক শিক্ষা ইসলামি শিক্ষার অবিচ্ছেদ্য অংশ।"
