    "জিহাদের প্রকারভেদ: ইসলামের দৃষ্টিতে জিহাদ তিন প্রকার— (১) স্বীয় নফসের (প্রবৃত্তির) সাথে জিহাদ করা। যেমন হযরত মুহাম্মদ (স.) বলেছেন— অর্থ: “প্রকৃত মুজাহিদ সে ব্যক্তি, যে আল্লাহর আনুগত্য করার ব্যাপারে নিজের নফসের (কুপ্রবৃত্তির) সাথে জিহাদ করে।” (মুসনাদে আহমাদ) এরূপ জিহাদকে রাসূলুল্লাহ (স.) সবচাইতে বড় জিহাদ বলে অভিহিত করেছেন। তিনি বদর যুদ্ধ থেকে ফিরে এসে বলেছেন— অর্থ: “আমরা ছোট জিহাদ থেকে বড় জিহাদের (কুপ্রবৃত্তির বিরুদ্ধে জিহাদ) দিকে ফিরে এসেছি।” (কানযুল উম্মাল) (২) জ্ঞানের সাহায্যে জিহাদ করা। এরূপ জিহাদকে পবিত্র কুরআনে জিহাদে কাবির (বড়) বলা হয়েছে। আল্লাহ বলেন— অর্থ: “সুতরাং আপনি কাফিরদের আনুগত্য করবেন না এবং আপনি কুরআনের (জ্ঞানের) সাহায্যে তাদের সাথে প্রবল জিহাদ চালিয়ে যান।” (সূরা আল-ফুরকান, আয়াত ৫২) (৩) ইসলামের শত্রুদের বিরুদ্ধে যুদ্ধ করা। এটি হলো জিহাদের সর্বোচ্চ স্তর। কেউ ধর্মদ্রোহী হয়ে ইসলামের বিরুদ্ধে আঘাত হানলে তার বিরুদ্ধে যুদ্ধ করা।"
