    "সন্ত্রাসবাদ বলতে আমরা বুঝি পার্থিব কোনো স্বার্থ লাভের আশায় বিশৃঙ্খলা ও তাণ্ডবলীলার মাধ্যমে জনসাধারণের মনে আতঙ্ক সৃষ্টি করা ও তাদের ক্ষতি করা। ইসলামি জ্ঞানের স্বল্পতার কারণে এক শ্রেণির লোক জিহাদ ও সন্ত্রাসকে এক করে ফেলেছে। বস্তুত উভয়ের মাঝে বিশাল পার্থক্য বিদ্যমান। বলা যায়, এ দুটো পরস্পর বিপরীত। রাজ্য জয়, ক্ষমতা দখল, সম্পদের লোভ, খুন-খারাবি, লুটতরাজ এবং অন্যায় রক্তপাত জিহাদের উদ্দেশ্য নয়। বরং মানুষকে মানুষের দাসত্ব থেকে মুক্ত করে আল্লাহর দাসত্বে নিয়ে আসা এবং জুলুম ও শোষণের অবসান ঘটিয়ে ইনসাফ ও ন্যায়ের সুশীতল ছায়াতলে নিয়ে আসাই জিহাদের উদ্দেশ্য। আল্লাহ তায়ালা বলেন— অর্থ: “আর তোমরা তাদের বিরুদ্ধে সংগ্রাম করতে থাকবে যতক্ষণ না ফিতনা দূরীভূত হয় এবং আল্লাহর দীন সামগ্রিকভাবে প্রতিষ্ঠিত হয়।” (সূরা আল-আনফাল, আয়াত ৩৯) পক্ষান্তরে, সন্ত্রাসবাদের উদ্দেশ্য হলো অন্যায়ভাবে রক্তপাত করে রাজ্য জয়, ক্ষমতা দখল, সম্পদ অর্জন করা এবং লুটতরাজ ও খুন-খারাবির মাধ্যমে নিজের শ্রেষ্ঠত্ব ও কর্তৃত্ব প্রতিষ্ঠা করা।",
    "ইসলাম জিহাদের মাধ্যমে মুসলমানদের রক্তপাত করতে শিখায়নি। বরং ইসলাম যে জিহাদের কথা বলে তাতে রক্তপাত নয়, মানবতার দিকনির্দেশনা দেয়। মুসলমানদের কোনো জিহাদেই নিরপরাধ সাধারণ লোকজনের কোনো ক্ষতি হয়নি। রাসূলুল্লাহ (স.)-এর জীবদ্দশায় তিনি প্রায় একশত-এর কাছাকাছি জিহাদে (যুদ্ধে) প্রত্যক্ষ ও পরোক্ষভাবে অংশগ্রহণ করেছেন। সবগুলো জিহাদ মিলিয়ে উভয়পক্ষে পাঁচশত এর কম লোকের প্রাণহানির ঘটনা ঘটেছে বলে ইতিহাস সাক্ষ্য দেয়। বর্তমান যুগে জিহাদের নামে যেভাবে বোমাবাজি, জঙ্গিবাদ, খুন-খারাবি ও নিরীহ লোকজনকে হত্যা করে নৈরাজ্য সৃষ্টি করা হচ্ছে, তার সাথে ইসলামের কোনো সম্পর্ক নেই। বরং এটা সন্ত্রাসেরই নামান্তর। বস্তুত জিহাদ ও সন্ত্রাসবাদ এক নয়। উপরোক্ত আলোচনা ও বাস্তব ইতিহাস পর্যালোচনা করলে আমরা দেখতে পাই যে, জিহাদে সন্ত্রাসবাদের কোনো স্থান নেই। জিহাদের সাথে সন্ত্রাসবাদের সম্পর্ক নেই।"
