    "ওয়াদা পালন আখলাকে হামিদাহর অন্যতম গুণ। মানবজীবনে এর গুরুত্ব ও প্রয়োজনীয়তা অপরিসীম। ওয়াদা পালন সমাজে শান্তি ও শৃঙ্খলা প্রতিষ্ঠা করে। যে ব্যক্তি ওয়াদা পালন করে তাকে সবাই ভালোবাসে। তার প্রতি সকলের আস্থা ও বিশ্বাস থাকে। সমাজে সে শ্রদ্ধা ও মর্যাদা লাভ করে। ইসলামি জীবন দর্শনে ওয়াদা পালন করা আবশ্যক। স্বয়ং আল্লাহ তায়ালা মানুষকে ওয়াদা পূর্ণ করার জন্য নির্দেশ প্রদান করেছেন। তিনি বলেছেন— অর্থ: “হে ইমানদারগণ! তোমরা অঙ্গীকারসমূহ পূর্ণ কর।” (সূরা আল-মায়িদা, আয়াত ১) অন্য আরেকটি আয়াতে আল্লাহ তায়ালা বলেন— অর্থ: “আর তোমরা প্রতিশ্রুতি পালন কর। নিশ্চয়ই প্রতিশ্রুতি সম্পর্কে জিজ্ঞাসা করা হবে।” (সূরা বনী ইসরাইল, আয়াত ৩৪) প্রতিশ্রুতি ও ওয়াদা পালন করা অত্যাবশ্যক। হাশরের ময়দানে প্রতিশ্রুতির ব্যাপারে মানুষকে জবাবদিহি করতে হবে। যে ব্যক্তি দুনিয়াতে ওয়াদা পালন করে না, আখিরাতে সে শাস্তি ভোগ করবে।"
