    "শালীনতা অর্থ মার্জিত, সুন্দর ও শোভন হওয়া। কথা-বার্তা, আচার-আচরণ ও চলাফেরায় ভদ্র, সভ্য ও মার্জিত হওয়াকেই শালীনতা বলা হয়। গর্ব-অহংকার, ঔদ্ধত্য ও অশ্লীলতা ত্যাগ করে জীবনাচরণের সকল ক্ষেত্রে ইসলামি নীতি-আদর্শের অনুসারী হওয়ার দ্বারা শালীনতা অর্জন করা যায়। শালীনতার পরিধি অত্যন্ত ব্যাপক। এটি বহু নৈতিক গুণের সমষ্টি। ভদ্রতা, নম্রতা, সৌন্দর্য, সুরুচি, লজ্জাশীলতা ইত্যাদি গুণাবলির সমন্বিত রূপের মাধ্যমে শালীনতা প্রকাশ পায়। অশ্লীলতা হলো শালীনতার বিপরীত। গর্ব-অহংকার, ঔদ্ধত্য, কুরুচি ও কুসংস্কার শালীনতাবিরোধী অভ্যাস। এগুলো থেকে বেঁচে থাকাই শালীনতা অর্জনের উপায়।",
