    "কর্তব্যপরায়ণতার নানা দিক: কর্তব্যপরায়ণতা মানবজীবনে সফলতা লাভের প্রধানতম হাতিয়ার। আল্লাহ তায়ালা তাঁর ইবাদতের জন্য আমাদের সৃষ্টি করেছেন। সুতরাং তাঁর ইবাদত করা আমাদের কর্তব্য। আমরা সবাই পরিবারের মধ্যে বসবাস করি। সুতরাং পরিবারের সদস্য যথা মাতা-পিতা, ভাই-বোন, দাদা-দাদি সকলের প্রতি আমাদের নানা দায়িত্ব ও কর্তব্য রয়েছে। সমাজবদ্ধ জীব হিসেবে আত্মীয়-পরিজন, বন্ধু-বান্ধব, পাড়া-প্রতিবেশীর প্রতিও আমাদের নানা দায়িত্ব ও কর্তব্য পালন করতে হয়। শিক্ষার্থী হিসেবে বিদ্যালয়, শিক্ষক ও অন্য শিক্ষার্থীর প্রতি আমাদের নানা কর্তব্য রয়েছে। এ ছাড়াও রাষ্ট্রীয়, জাতীয় ও আন্তর্জাতিক দায়িত্ব ও কর্তব্য আসলেও আমাদের পালন করতে হয়।"
