    "হিংসা আখলাকে যামিমাহ-র অন্যতম দিক। হিংসা-বিদ্বেষ মানে অন্যের প্রতি বিরূপ মনোভাব পোষণ করা, নিজেকে বড় মনে করা, অন্যকে ঘৃণা করা, শত্রুতাবশত অন্যের ক্ষতি কামনা করা, অন্যের উন্নতি, সুখ সহ্য করতে না পারা ইত্যাদি। ইসলামি পরিভাষায় অন্যের সুখ-সম্পদ, শান্তি-সাফল্য ধ্বংস হওয়া ও নিজে এর মালিক হওয়ার কামনাকে হিংসা বলা হয়। আরবি ভাষায় হিংসার প্রতিশব্দ হলো হাসাদ।",
    "হিংসার কুফল: হিংসা-বিদ্বেষ মানব চরিত্রের অত্যন্ত নিন্দনীয় অভ্যাস। এটি মানব চরিত্রকে ধ্বংস করে দেয়। হিংসুক ব্যক্তি কখনোই সচ্চরিত্রবান হতে পারে না। কেননা গর্ব-অহংকার, পরশ্রীকাতরতা, শত্রুতা, অন্যের অনিষ্ট কামনা ইত্যাদি হিংসার সাথে অঙ্গাঙ্গিভাবে জড়িত। একটি হাদিসে মহানবি (স.) বলেছেন, “পরস্পর কল্যাণকামিতাই হলো দীন।” হিংসা এসব সদ্গুণ ধ্বংস করে দেয়। হিংসা-বিদ্বেষ জাতীয় ঐক্য, সংহতি ও উন্নতির পথে অন্তরায়। এর ফলে জাতির মধ্যে বিভেদ বৈষম্য দেখা দেয়, শত্রুতা বৃদ্ধি পায়। এতে মুসলিম জাতির ঐক্য ও ভ্রাতৃত্ব নষ্ট হয়। রাসূলুল্লাহ (স.) বলেছেন, “তোমাদের পূর্ববর্তী জাতিসমূহের মুণ্ডনকারী (ধ্বংসকারী) রোগ— ঘৃণা ও হিংসা তোমাদের দিকে হামাগুড়ি দিয়ে এগিয়ে আসছে। আমি চুল মুণ্ডনের কথা বলছি না, বরং তা হলো দীনের মুণ্ডনকারী।” (তিরমিযি) হিংসা মানুষের সকল নেক আমলকে ধ্বংস করে দেয়। মহানবি (স.) বলেছেন— অর্থ: “তোমরা হিংসা থেকে বেঁচে থাকো। কেননা আগুন যেমন কাঠকে খেয়ে ফেলে (পুড়িয়ে দেয়), হিংসাও তেমনি মানুষের সৎকর্মগুলোকে খেয়ে ফেলে (নষ্ট করে দেয়)।” (আবু দাউদ) অন্য হাদিসে রাসূলুল্লাহ (স.) বলেছেন, “তিন ব্যক্তির গুনাহ মাফ হয় না। অন্যদের একজন হচ্ছে অন্যের প্রতি বিদ্বেষ পোষণকারী।” (আদাবুল মুফরাদ)"
