    "কুফল: কর্মবিমুখতা মানুষের মধ্যে অলসতা সৃষ্টি করে। এতে মানুষ অকর্মণ্য হয়ে পড়ে। মানুষের কর্মস্পৃহা, কর্মক্ষমতা লোপ পায়। বলা হয় ‘অলস মস্তিষ্ক শয়তানের কারখানা’। অলস ব্যক্তিরা নানা অসৎ ও অনৈতিক চিন্তা ও কর্মে ব্যাপৃত থাকে। কর্মবিমুখতার ফলে মানুষের মেধা, শক্তি ও সময়ের অপচয় হয়। কর্মবিমুখ বেকারকে কেউ ভালোবাসে না। কর্মবিমুখতা মানুষের আত্মসম্মানবোধ লোপ করে। অন্যের অর্থে জীবনযাপন করার মানসিকতা তৈরি হয়। এতে মানুষ হতাশ হয়ে পড়ে। অনেক সময় আত্মহত্যার পথ বেছে নেয়। কর্মবিমুখ জাতি কখনো উন্নতি করতে পারে না। কর্মবিমুখতা একটি জাতির জন্য দুর্ভাগ্য, কলঙ্ক স্বরূপ।"
