    "ইবনে আব্দুল মালিক আল কাসি: তাঁর নাম আবুল হাকিম মুহাম্মদ ইবনে আব্দুল মালিক আল খারেজমি আল কাসি। তিনি একাদশ শতাব্দীতে বাগদাদে জন্মগ্রহণ করেন। তাঁর লেখা ‘আইনুস সানাহ ওয়া আইওয়ানুন সানাহ’ (Essence of the Art and Aid of worker) এ গ্রন্থটি রসায়নশাস্ত্রে মূল্যবান একটি সংযোজন। তিনি এ গ্রন্থে রসায়নের প্রত্যেক প্রয়োজনীয় শাখার সরল ও সহজ পন্থা সংক্ষিপ্তভাবে উল্লেখ করেছেন। যে সকল বস্তু ‘সাদা’ এবং যে সকল বস্তু ‘লাল’ এদের ব্যবহার ও পার্থক্য বিস্তারিতভাবে বর্ণনা করেছেন।"
