    "আল মোকাদ্দাসি: তাঁর নাম মুহাম্মদ, পিতার নাম আহমাদ। তিনি ৯৪৬ খ্রি. বাইতুল মোকাদ্দাস এলাকায় জন্মগ্রহণ করেন তাই আল মোকাদ্দাসি নামে পরিচিত। তিনি একজন বিখ্যাত পর্যটক ও ভূগোলবিদ ছিলেন। তিনি স্পেন, ভারতবর্ষ ও সিজিস্তান ব্যতীত সমগ্র মুসলিম বিশ্ব ভ্রমণ করেন। দীর্ঘ বিশ বছরের ভ্রমণ অভিজ্ঞতার আলোকে তিনি ৯৮৫ পৃষ্ঠার একটি গ্রন্থ রচনা করেন। তাঁর গ্রন্থের নাম হলো ‘আহসানুত তাকাসিম ফি মারিফাতুল আকাসিম’। এই মনীষী ১০০০ খ্রিষ্টাব্দে ইন্তেকাল করেন।",
